mapper.select:
SELECT 
  FROM emp53_biz_trip
       LEFT OUTER JOIN apr01_appr apr01 ON apr01.apr01_appr_id = emp53_appr_id
       LEFT OUTER JOIN apr01_appr apr02 ON apr02.apr01_appr_id = emp53_result_appr_id
 WHERE emp53_biz_trip_id = #{bizTripId}
   AND emp53_company_id = #{companyId}

SELECT 
  FROM emp53_biz_trip
       LEFT OUTER JOIN apr01_appr apr01 ON apr01.apr01_appr_id = emp53_appr_id
       LEFT OUTER JOIN apr01_appr apr02 ON apr02.apr01_appr_id = emp53_result_appr_id
 WHERE emp53_company_id = #{companyId}
   AND emp53_person_id = #{personId}
   AND emp53_start_date BETWEEN #{startDate} AND #{closeDate}
   AND UPPER(CONCAT(emp53_destination, emp53_purpose)) LIKE UPPER(#{searchText})
 ORDER BY emp53_start_date DESC

SELECT 
  FROM emp53_biz_trip
       LEFT OUTER JOIN apr01_appr apr01 ON apr01.apr01_appr_id = emp53_appr_id
       LEFT OUTER JOIN apr01_appr apr02 ON apr02.apr01_appr_id = emp53_result_appr_id
 WHERE emp53_biz_trip_id = #{bizTripId}
   AND emp53_company_id = #{companyId}
   AND emp53_person_id = #{personId}

mapper.update:
UPDATE emp53_biz_trip
   SET emp53_appr_id = #{apprId}
 WHERE emp53_biz_trip_id = #{bizTripId}
   AND emp53_company_id  = #{companyId}
   AND emp53_person_id   = #{personId}

UPDATE emp53_biz_trip
   SET emp53_result_appr_id = #{apprId}
 WHERE emp53_biz_trip_id = #{bizTripId}
   AND emp53_company_id  = #{companyId}
   AND emp53_person_id   = #{personId}

UPDATE emp53_biz_trip
   SET emp53_public_yn = CAST(#{publicYn} AS VARCHAR)
 WHERE emp53_biz_trip_id = #{bizTripId}
   AND emp53_company_id  = #{companyId}
   AND emp53_person_id   = #{personId}

